<?php
namespace App\Http\Middleware;
use Closure;use Illuminate\Http\Request;use Symfony\Component\HttpFoundation\Response;
class ProductionSecurity{public function handle(Request$request,Closure$next):Response{$protected=in_array('auth',$request->route()?->gatherMiddleware()??[],true);if(app()->environment('staging','production')){abort_unless($request->isSecure(),400,'HTTPS is required.');$expected=parse_url((string)config('app.url'),PHP_URL_HOST);abort_unless($expected&&hash_equals(strtolower($expected),strtolower($request->getHost())),400,'Invalid host.');}$response=$next($request);$response->headers->set('X-Content-Type-Options','nosniff');$response->headers->set('X-Frame-Options','SAMEORIGIN');$response->headers->set('Referrer-Policy','strict-origin-when-cross-origin');$response->headers->set('Permissions-Policy','camera=(), microphone=(), geolocation=()');$cache=(string)$response->headers->get('Cache-Control');if(($protected||$request->routeIs('otp.show','password.reset'))&&!str_contains($cache,'no-store'))$response->headers->set('Cache-Control','no-store, no-cache, must-revalidate, private');if($request->isSecure()&&app()->environment('production'))$response->headers->set('Strict-Transport-Security','max-age=31536000; includeSubDomains');return$response;}}
